  };

  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold">{t('features.title')}</h1>
        <p className="text-muted-foreground">
          {t('features.subtitle')}
        </p>
      </div>
      {renderContent()}
    </div>
  );
}

